    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i; pairs[i]=j
seq=['A']*len(target)
for i,j in pairs.items():
    if i<j:
        seq[i]='G'; seq[j]='C'
print(''.join(seq))
"

